#[test]
fn test_every_fixture_dump_is_its_golden() {
    // Row: file, golden. The dump of the file, read in memory, is the golden's bytes (less its line feed):
    // every element with its role and how it was found, its kids, attributes and text properties, every
    // marked-content reference with the span it joined, the artifact spans, and the score, on all four targets.
    let f: &[u8] = &crate::testport::test_file("pdf/tagged.txt")[..];
    let n: i32 = crate::port::blob_len(f);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut rows: i32 = 0;
    let mut e: i32 = 0;
    let mut s0: i32 = 0;
    while pos < n {
        line += 1;
        e = tt_nl(f, pos);
        if (pos < e) && (crate::port::blob_u8(f, pos) != 35) {
            rows += 1;
            s0 = tt_tab(f, pos, e);
            let t: &mut String = &mut crate::port::new_text();
            let g: &[u8] = &crate::testport::test_file_span(f, s0 + 1, e)[..];
            crate::testport::assert_eq_at(tt_dump(&crate::port::src_of_blob(&crate::testport::test_file_span(f, pos, s0)[..]), t), 0, "opened and read", line);
            crate::testport::assert_text_span(t, g, 0, crate::port::blob_len(g) - 1, "the golden", line);
        }
        pos = e + 1;
    }
    crate::testport::assert_that(rows >= 10, "the fixtures were read");
}
pub(crate) fn tt_say(pdf: &[u8], which: i32, mut t: &mut String) -> i32 {
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    return tt_line(&crate::port::src_of_blob(pdf), which, t, res);
}
pub(crate) fn tt_score(pdf: &[u8]) -> i32 {
    // The score of a file, -1 when it did not read.
    let res: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t: &mut String = &mut crate::port::new_text();
    if tt_line(&crate::port::src_of_blob(pdf), 7, t, res) != 0 {
        return -1;
    }
    return crate::port::cells_at(res, 0);
}
#[test]
fn test_the_correct_document_says_what_it_was_built_to_say() {
    // good.pdf: Document > H1 (a custom `Heading` the RoleMap makes H1), Body (custom, P), four Sect with an H2
    // each, a list of three items with Lbl and LBody and ListNumbering Decimal, a ruled table of three rows with
    // TH cells whose Scope comes through a class, a Figure with Alt, a Caption, a Span with ActualText and E, a French
    // paragraph. Header, footer, watermark and the rules are artifacts of the right Type and Subtype.
    let pdf: &[u8] = &crate::testport::test_file("pdf/tagged/good.pdf")[..];
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    let t3: &mut String = &mut crate::port::new_text();
    let t4: &mut String = &mut crate::port::new_text();
    let t5: &mut String = &mut crate::port::new_text();
    let t6: &mut String = &mut crate::port::new_text();
    crate::testport::assert_eq(tt_say(pdf, 1, t1), 0, "read");
    crate::testport::assert_text(t1, "Document:0 H1:1 P:1 Sect:0 H2:0 P:0 Sect:0 H2:0 L:0 LI:0 Lbl:0 LBody:0 LI:0 Lbl:0 LBody:0 LI:0 Lbl:0 LBody:0 Sect:0 H2:0 Table:0 TR:0 TH:0 TH:0 TH:0 TR:0 TD:0 TD:0 TD:0 TR:0 TD:0 TD:0 TD:0 Sect:0 H2:0 P:0 Span:0 Span:0 Figure:0 Caption:0 P:0", "roles and how");
    crate::testport::assert_eq(tt_say(pdf, 2, t2), 0, "read");
    crate::testport::assert_text(t2, "1: lang=en-US from=1 | 37: actual=third quarter exp=Quarter three from=1 | 39: alt=Bar chart of revenue by month from=1 | 41: lang=fr-FR from=41", "text properties");
    crate::testport::assert_eq(tt_say(pdf, 3, t3), 0, "read");
    crate::testport::assert_text(t3, "L items=3 labelled=3 agree=3 differ=0 numbering=Decimal kind=2 | Table rows=3 cols=3 regular=1 summary=Revenue and growth by region | TH scope=2 rowspan=-1 colspan=-1 headers=- | TH scope=2 rowspan=-1 colspan=-1 headers=- | TH scope=2 rowspan=-1 colspan=-1 headers=-", "tables and lists");
    crate::testport::assert_eq(tt_say(pdf, 4, t4), 0, "read");
    crate::testport::assert_text(t4, "28 0 0 | 594 545 49 0 0 | 2 28 0 0 | 42 28 0", "the join: every reference joined, 545 glyphs owned by an element and 49 in artifacts, the ParentTree agrees 28 times");
    crate::testport::assert_eq(tt_say(pdf, 5, t5), 0, "read");
    crate::testport::assert_text(t5, "1.1@2:1(16) 1.3@1:1(5) 3.0@0:0(0) 1.2@3:1(6) 1.1@2:1(16) 1.2@3:1(6)", "artifacts: a header at the top, a turned watermark, the rules (no text), a footer at the bottom, again");
    crate::testport::assert_eq(tt_say(pdf, 6, t6), 0, "read");
    crate::testport::assert_text(t6, "1000 1000 1000 1000 1000 1000 1000 1000", "the score: every component and the whole");
}
