pub(crate) fn tt_survive(pdf: &crate::port::Src) -> i32 {
    let t: &mut String = &mut crate::port::new_text();
    return tt_dump(pdf, t);
}
pub(crate) fn tt_cut(f: &[u8], n: i32, mut cut: &mut crate::port::Cells) -> i32 {
    let mut i: i32 = 0;
    crate::port::cells_drop(cut, 0);
    while i < n {
        crate::port::cells_push(cut, crate::port::blob_u8(f, i));
        i += 1;
    }
    return n;
}
pub(crate) fn tt_truncations(f: &[u8], step: i32, mut cut: &mut crate::port::Cells) -> i32 {
    // Every truncation of f, every `step` bytes: none may fault. Answers how many still read.
    let n: i32 = crate::port::blob_len(f);
    let mut k: i32 = 0;
    let mut ok: i32 = 0;
    while k <= n {
        tt_cut(f, k, cut);
        if tt_survive(&crate::port::src_of_blob(&crate::testport::cells_blob(cut)[..])) == 0 {
            ok += 1;
        }
        k += step;
    }
    return ok;
}
pub(crate) fn tt_corruptions(f: &[u8], rounds: i32, flips: i32, seed: i32, mut cut: &mut crate::port::Cells, mut rng: &mut crate::port::Cells) -> i32 {
    // `rounds` copies of f with `flips` random bytes replaced (SplitMix, so every target damages the same bytes):
    // none may fault. Answers how many still read.
    let n: i32 = crate::port::blob_len(f);
    let mut r: i32 = 0;
    let mut j: i32 = 0;
    let mut at: i32 = 0;
    let mut ok: i32 = 0;
    sm_seed(rng, seed as i64);
    while r < rounds {
        tt_cut(f, n, cut);
        j = 0;
        while j < flips {
            at = sm_below(rng, n);
            crate::port::cells_set(cut, at, sm_below(rng, 256));
            j += 1;
        }
        if tt_survive(&crate::port::src_of_blob(&crate::testport::cells_blob(cut)[..])) == 0 {
            ok += 1;
        }
        r += 1;
    }
    return ok;
}
#[test]
fn test_no_truncation_of_a_fixture_faults() {
    // Every 97th cut of each tagged fixture (a tree cut anywhere): nothing faults.
    let cut: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_that(tt_truncations(&crate::testport::test_file("pdf/tagged/good.pdf")[..], 97, cut) >= 1, "good");
    crate::testport::assert_that(tt_truncations(&crate::testport::test_file("pdf/tagged/bad-artifacts.pdf")[..], 97, cut) >= 1, "bad-artifacts");
    crate::testport::assert_that(tt_truncations(&crate::testport::test_file("pdf/tagged/odd.pdf")[..], 61, cut) >= 1, "odd");
}
#[test]
fn test_no_corruption_of_a_fixture_faults() {
    // Copies with three bytes replaced: a wrong /K, /P, /Pg, /MCID, /S, /Nums, a broken RoleMap; none faults.
    let cut: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rng: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_that(tt_corruptions(&crate::testport::test_file("pdf/tagged/good.pdf")[..], 120, 3, 1, cut, rng) >= 0, "good");
    crate::testport::assert_that(tt_corruptions(&crate::testport::test_file("pdf/tagged/odd.pdf")[..], 120, 3, 2, cut, rng) >= 0, "odd");
    crate::testport::assert_that(tt_corruptions(&crate::testport::test_file("pdf/tagged/bad-order.pdf")[..], 120, 4, 3, cut, rng) >= 0, "bad-order");
}
pub(crate) fn tt_async(bytes: &[u8], chunk: i32, mut t: &mut String) -> i32 {
    // Read `bytes` through an async source of `chunk`-byte chunks, re-running until an attempt does not miss; the dump
    // of that attempt goes to t. Answers that attempt's verdict, or -2 after 40 rounds.
    let base: &crate::port::Src = &crate::testport::src_chunked(bytes, chunk, 0);
    let mut round: i32 = 0;
    let mut more: i32 = 1;
    let mut verdict: i32 = 0;
    while more == 1 {
        let v: &crate::port::Src = &crate::testport::src_view(base);
        verdict = tt_dump(v, t);
        if ps_missed(v) {
            crate::testport::src_ctl(base, 0, round);
            round += 1;
            if round > 40 {
                more = 0;
                verdict = -2;
            }
        } else {
            more = 0;
        }
    }
    return verdict;
}
#[test]
fn test_fixtures_through_an_async_source_are_their_golden_bytes() {
    // D075: a missed attempt answers -1 and writes nothing; the host fetches what was missed and re-runs on a fresh
    // view. The correct document and the odd one, through 64-byte chunks, are their goldens.
    let t: &mut String = &mut crate::port::new_text();
    let g: &[u8] = &crate::testport::test_file("pdf/tagged/good.json")[..];
    crate::testport::assert_eq(tt_async(&crate::testport::test_file("pdf/tagged/good.pdf")[..], 64, t), 0, "read");
    crate::testport::assert_text_span(t, g, 0, crate::port::blob_len(g) - 1, "good through 64-byte chunks", 1);
    let t2: &mut String = &mut crate::port::new_text();
    let g2: &[u8] = &crate::testport::test_file("pdf/tagged/odd.json")[..];
    crate::testport::assert_eq(tt_async(&crate::testport::test_file("pdf/tagged/odd.pdf")[..], 512, t2), 0, "read");
    crate::testport::assert_text_span(t2, g2, 0, crate::port::blob_len(g2) - 1, "odd through 512-byte chunks", 2);
}
